function bookCase(r){
  for(var tries=0; tries<40; tries++){ var c=bookCase1(r); if(c.res.ka>0 && c.res.tax>0) return c; } return c;
}
function bookCase1(r){
  var f = function(a,b,s){ return rnd(r,a,b,s)*1000; };
  var o = { gr: f(300,500,50), ma: f(600,1000,50), rhb: f(80,150,10), feS: rnd(r,15,25,1)*1000, feW: rnd(r,18,22,1), fo: f(250,400,10), ka: f(250,450,10), rg: f(80,120,10), rr: f(40,60,10) };
  o.fe = o.feS*o.feW; var aktiva = o.gr+o.ma+o.rhb+o.fe+o.fo+o.ka; o.vki = Math.round(aktiva*rnd(r,0.4,0.5,0.01)/10000)*10000; o.ek = aktiva - o.vki - o.rg - o.rr;
  var hk = o.feW + rnd(r,1,3,1), prod = rnd(r,60,90,5)*1000, vk = prod - rnd(r,1,4,1)*1000, p = hk + rnd(r,2,5,1);
  var g = { fz: Math.min(o.fo, f(80,150,10)), rk: f(700,1000,50), rkz: 0, mv: 0, an: f(100,300,50), ge: f(400,700,50), ze: 0, zr: f(80,120,10), gw: 0, zi: f(50,100,10), so: f(150,300,10), afa: 0, rep: 0 };
  g.rkz = Math.round(g.rk*rnd(r,0.5,0.7,0.05)/10000)*10000; g.mv = Math.round((g.rk*rnd(r,0.7,0.85,0.05))/10000)*10000;
  var ums = vk*p; g.ze = Math.round(ums*rnd(r,0.85,0.95,0.01)/10000)*10000; g.gw = Math.round(g.zr*rnd(r,0.6,0.9,0.1)/1000)*1000; g.afa = Math.round((o.ma+g.an)*0.2/10000)*10000; g.rep = o.rr - rnd(r,1,2,1)*5000;
  var avg = (o.fe + prod*hk)/(o.feS + prod), abg = Math.round(vk*avg), bv = prod*hk - abg;
  var ebt = ums + bv + (o.rr - g.rep) - g.mv - g.ge - g.zr - g.zi - g.so - g.afa, tax = Math.max(0, Math.round(ebt*0.25)); var ju = ebt - tax;
  var L = [
   ["Einzahlung von Forderungen aus dem Vorjahr", g.fz, 5, 4], ["Kauf von Roh-, Hilfs- und Betriebsstoffen auf Rechnung", g.rk, 2, 8], ["Bezahlung eines Teils der Rechnungen aus Vorgang 2", g.rkz, 8, 5],
   ["Entnahme von Material für die Produktion", g.mv, 14, 2], ["Kauf und Bezahlung einer neuen Produktionsanlage", g.an, 1, 5], ["Gehälter, bezahlt", g.ge, 15, 5],
   ["Produktion von " + eur(prod,0) + " Fertigprodukten zu Herstellungskosten von " + eur(hk) + " € je Stück und Einlagerung", prod*hk, 3, 12],
   ["Verkauf von " + eur(vk,0) + " Fertigprodukten auf Rechnung zu " + eur(p) + " € je Stück (Erlösbuchung)", ums, 4, 11],
   ["Abgang der " + eur(vk,0) + " verkauften Fertigprodukte vom Lager, bewertet zum gewogenen Durchschnitt (auf volle Euro gerundet)", abg, 12, 3],
   ["Zahlungseingang aus Vorgang 8", g.ze, 5, 4], ["Zuführung zur Rückstellung für Gewährleistung", g.zr, 17, 9], ["Gewährleistung im laufenden Jahr, bar an Kunden vergütet", g.gw, 9, 5],
   ["Die Bank zieht den Zinsaufwand ein", g.zi, 18, 5], ["Sonstiger zahlungswirksamer Aufwand", g.so, 19, 5], ["Abschreibung des Anlagevermögens", g.afa, 16, 1],
   ["Die im Vorjahr unterlassene Reparatur wird ausgeführt; Rechnung der Fremdfirma", g.rep, 10, 8], ["Auflösung des Rests der Reparaturrückstellung", o.rr - g.rep, 10, 13],
   ["Steuern vom Einkommen und Ertrag (25 % auf den Gewinn vor Steuern), per Bank bezahlt", tax, 20, 5]];
  var bal = { gr: o.gr, ma: o.ma + g.an - g.afa, rhb: o.rhb + g.rk - g.mv, fe: o.fe + prod*hk - abg, fo: o.fo - g.fz + ums - g.ze };
  bal.ka = o.ka + g.fz - g.rkz - g.an - g.ge + g.ze - g.gw - g.zi - g.so - tax;
  var bs = bal.gr + bal.ma + bal.rhb + bal.fe + bal.fo + bal.ka;
  return { o: o, lines: L, res: { ju: ju, bs: bs, ka: bal.ka, fe: bal.fe, ek: o.ek + ju, bv: bv, tax: tax }, avg: avg, hk: hk };
}

